/* @lc app=leetcode id=3419 lang=kotlin */ class Solution { fun minMaxWeight(n: Int, edges: Array<IntArray>, threshold: Int): Int = edges.groupBy({ it[1] }, { it[0] to it[2] }).let { rg -> IntArray(n) { Int.MAX_VALUE }.also { it[0] = 0 }.let { d -> java.util.PriorityQueue<IntArray>(compareBy<IntArray> { it[0] }).also { it.add(intArrayOf(0, 0)) }.let { pq -> generateSequence { pq.poll() }.filter { (c, u) -> c == d[u] }.forEach { (c, u) -> rg[u].orEmpty().filter { (v, w) -> maxOf(c, w) < d[v] }.forEach { (v, w) -> pq.add(intArrayOf(maxOf(c, w), v)).also { d[v] = maxOf(c, w) } } }.let { if (d.any { it == Int.MAX_VALUE }) -1 else d.max() } } } } }